    <script>
class AIModelHub {
    constructor() {
        this.socket = io();
        this.selectedModel = null;
        this.currentFile = null;
        this.isProcessing = false;

        this.initializeApp();
        this.setupEventListeners();
        this.setupSocketHandlers();
    }

    initializeApp() {
        setTimeout(() => {
            document.getElementById('loading-screen').classList.add('hidden');
        }, 2000);

        this.initializePWA();
        this.loadModels();
    }

    initializePWA() {
        if ('serviceWorker' in navigator) {
            const swCode = `
                const CACHE_NAME = 'ai-modelhub-v1';
                const urlsToCache = ['/'];

                self.addEventListener('install', (event) => {
                    event.waitUntil(
                        caches.open(CACHE_NAME).then((cache) => cache.addAll(urlsToCache))
                    );
                });

                self.addEventListener('fetch', (event) => {
                    event.respondWith(
                        caches.match(event.request).then((response) => response || fetch(event.request))
                    );
                });
            `;

            const blob = new Blob([swCode], { type: 'application/javascript' });
            const swUrl = URL.createObjectURL(blob);

            navigator.serviceWorker.register(swUrl)
                .then(reg => console.log('SW registered'))
                .catch(err => console.log('SW registration failed'));
        }

        let deferredPrompt;
        window.addEventListener('beforeinstallprompt', (e) => {
            e.preventDefault();
            deferredPrompt = e;

            const installBtn = document.createElement('button');
            installBtn.className = 'btn-secondary install-btn';
            installBtn.innerHTML = '<i class="fas fa-download"></i> Telepítés';
            installBtn.onclick = () => {
                deferredPrompt.prompt();
                deferredPrompt.userChoice.then(() => {
                    deferredPrompt = null;
                    installBtn.remove();
                });
            };

            const headerRight = document.querySelector('.header-right');
            if (headerRight) {
                headerRight.appendChild(installBtn);
            }
        });
    }

    setupEventListeners() {
        // Model selection
        document.querySelectorAll('.model-card').forEach(card => {
            card.addEventListener('click', () => {
                this.selectModel(card.dataset.model);
            });
        });

        // File upload
        const uploadArea = document.getElementById('upload-area');
        const fileInput = document.getElementById('file-input');

        uploadArea.addEventListener('click', () => fileInput.click());

        uploadArea.addEventListener('dragover', (e) => {
            e.preventDefault();
            uploadArea.classList.add('dragover');
        });

        uploadArea.addEventListener('dragleave', () => {
            uploadArea.classList.remove('dragover');
        });

        uploadArea.addEventListener('drop', (e) => {
            e.preventDefault();
            uploadArea.classList.remove('dragover');
            if (e.dataTransfer.files.length > 0) {
                this.handleFileSelect(e.dataTransfer.files[0]);
            }
        });

        fileInput.addEventListener('change', (e) => {
            if (e.target.files.length > 0) {
                this.handleFileSelect(e.target.files[0]);
            }
        });

        // Process button
        document.getElementById('process-btn').addEventListener('click', () => {
            this.processFile();
        });

        // New process button
        document.getElementById('new-process-btn').addEventListener('click', () => {
            this.resetApp();
        });

        // Settings button
        document.getElementById('settings-btn').addEventListener('click', () => {
            this.showSettings();
        });
    }

    setupSocketHandlers() {
        this.socket.on('connect', () => {
            console.log('WebSocket connected');
        });

        this.socket.on('processing_update', (data) => {
            this.updateProcessingStatus(data);
        });

        this.socket.on('processing_complete', (data) => {
            this.handleProcessingComplete(data);
        });
    }

    async loadModels() {
        try {
            const response = await fetch('/api/models');
            const models = await response.json();
            console.log('Models loaded:', models);
        } catch (error) {
            console.error('Error loading models:', error);
        }
    }

    selectModel(modelName) {
        document.querySelectorAll('.model-card').forEach(card => {
            card.classList.remove('selected');
        });

        const selectedCard = document.querySelector(`[data-model="\${modelName}"]`);
        selectedCard.classList.add('selected');

        this.selectedModel = modelName;
        this.showModelParameters(modelName);
        this.updateProcessButton();

        document.getElementById('upload-section').scrollIntoView({
            behavior: 'smooth',
            block: 'start'
        });
    }

    showModelParameters(modelName) {
        const parametersContainer = document.getElementById('model-parameters');
        parametersContainer.innerHTML = '';

        const parameters = this.getModelParameters(modelName);

        if (parameters.length > 0) {
            const title = document.createElement('h3');
            title.textContent = 'Modell paraméterek';
            title.style.color = 'var(--text-primary)';
            title.style.marginBottom = 'var(--spacing-md)';
            parametersContainer.appendChild(title);

            parameters.forEach(param => {
                const group = document.createElement('div');
                group.className = 'parameter-group';

                const label = document.createElement('label');
                label.textContent = param.label;
                label.setAttribute('for', param.id);

                let input;
                if (param.type === 'select') {
                    input = document.createElement('select');
                    param.options.forEach(option => {
                        const optionElement = document.createElement('option');
                        optionElement.value = option.value;
                        optionElement.textContent = option.label;
                        input.appendChild(optionElement);
                    });
                } else {
                    input = document.createElement('input');
                    input.type = param.type;
                    if (param.min) input.min = param.min;
                    if (param.max) input.max = param.max;
                    if (param.step) input.step = param.step;
                }

                input.id = param.id;
                input.name = param.name;
                input.value = param.default;

                group.appendChild(label);
                group.appendChild(input);
                parametersContainer.appendChild(group);
            });
        }
    }

    getModelParameters(modelName) {
        const parameterSets = {
            chain_of_zoom: [
                {
                    id: 'zoom_factor',
                    name: 'zoom_factor',
                    label: 'Zoom szorzó',
                    type: 'select',
                    default: '64',
                    options: [
                        { value: '4', label: '4x' },
                        { value: '16', label: '16x' },
                        { value: '64', label: '64x' },
                        { value: '256', label: '256x' }
                    ]
                }
            ],
            phhofm_sisr: [
                {
                    id: 'model_type',
                    name: 'model_type',
                    label: 'Modell típus',
                    type: 'select',
                    default: '2xPublic_realplksr',
                    options: [
                        { value: '2xPublic_realplksr', label: '2x RealPLKSR' },
                        { value: '4xRealPLKSR_Otaku', label: '4x Otaku Real' },
                        { value: '2xHFA2kCompact', label: '2x HFA2k Compact' }
                    ]
                },
                {
                    id: 'scale_factor',
                    name: 'scale_factor',
                    label: 'Skála szorzó',
                    type: 'number',
                    min: 1,
                    max: 4,
                    step: 1,
                    default: 2
                }
            ],
            ltx_video: [
                {
                    id: 'prompt',
                    name: 'prompt',
                    label: 'Videó prompt',
                    type: 'text',
                    default: 'Gyönyörű természeti táj'
                },
                {
                    id: 'duration',
                    name: 'duration',
                    label: 'Időtartam (sec)',
                    type: 'number',
                    min: 1,
                    max: 10,
                    step: 1,
                    default: 5
                },
                {
                    id: 'fps',
                    name: 'fps',
                    label: 'FPS',
                    type: 'select',
                    default: '24',
                    options: [
                        { value: '24', label: '24 FPS' },
                        { value: '30', label: '30 FPS' }
                    ]
                }
            ],
            dit_sr: [
                {
                    id: 'scale_factor',
                    name: 'scale_factor',
                    label: 'Skála szorzó',
                    type: 'select',
                    default: '4',
                    options: [
                        { value: '2', label: '2x' },
                        { value: '4', label: '4x' },
                        { value: '8', label: '8x' }
                    ]
                }
            ],
            urae: [
                {
                    id: 'task_type',
                    name: 'task_type',
                    label: 'Feladat típus',
                    type: 'select',
                    default: 'reconstruction',
                    options: [
                        { value: 'reconstruction', label: 'Rekonstrukció' },
                        { value: 'denoising', label: 'Zajszűrés' },
                        { value: 'enhancement', label: 'Javítás' }
                    ]
                },
                {
                    id: 'latent_dimension',
                    name: 'latent_dimension',
                    label: 'Latent dimenzió',
                    type: 'number',
                    min: 128,
                    max: 1024,
                    step: 128,
                    default: 512
                }
            ]
        };

        return parameterSets[modelName] || [];
    }

    handleFileSelect(file) {
        this.currentFile = file;

        if (!this.validateFile(file)) {
            return;
        }

        this.showFilePreview(file);
        this.updateProcessButton();
    }

    validateFile(file) {
        const maxSize = 16 * 1024 * 1024; // 16MB
        const allowedTypes = ['image/jpeg', 'image/png', 'image/webp', 'video/mp4', 'video/webm'];

        if (file.size > maxSize) {
            this.showError('A fájl mérete túl nagy (max 16MB)');
            return false;
        }

        if (!allowedTypes.includes(file.type)) {
            this.showError('Nem támogatott fájlformátum');
            return false;
        }

        return true;
    }

    showFilePreview(file) {
        const previewContainer = document.getElementById('file-preview');
        previewContainer.innerHTML = '';

        const previewItem = document.createElement('div');
        previewItem.className = 'file-preview-item';

        const fileReader = new FileReader();
        fileReader.onload = (e) => {
            const thumb = document.createElement(file.type.startsWith('video/') ? 'video' : 'img');
            thumb.className = 'file-preview-thumb';
            thumb.src = e.target.result;
            if (file.type.startsWith('video/')) {
                thumb.controls = false;
                thumb.muted = true;
            }

            const info = document.createElement('div');
            info.className = 'file-preview-info';
            info.innerHTML = `
                <h4>\${file.name}</h4>
                <p>\${this.formatFileSize(file.size)} • \${file.type}</p>
            `;

            previewItem.appendChild(thumb);
            previewItem.appendChild(info);
        };

        fileReader.readAsDataURL(file);
        previewContainer.appendChild(previewItem);
    }

    formatFileSize(bytes) {
        if (bytes === 0) return '0 Bytes';
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    }

    updateProcessButton() {
        const processBtn = document.getElementById('process-btn');
        const canProcess = this.selectedModel && this.currentFile && !this.isProcessing;

        processBtn.disabled = !canProcess;

        if (canProcess) {
            processBtn.innerHTML = '<i class="fas fa-play"></i> Feldolgozás indítása';
        } else if (this.isProcessing) {
            processBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Feldolgozás...';
        } else {
            processBtn.innerHTML = '<i class="fas fa-play"></i> Válasszon modellt és fájlt';
        }
    }

    async processFile() {
        if (!this.selectedModel || !this.currentFile || this.isProcessing) {
            return;
        }

        this.isProcessing = true;
        this.updateProcessButton();
        this.showProcessingSection();

        const formData = new FormData();
        formData.append('file', this.currentFile);

        // Add parameters
        const parameterInputs = document.querySelectorAll('#model-parameters input, #model-parameters select');
        parameterInputs.forEach(input => {
            formData.append(input.name, input.value);
        });

        try {
            const response = await fetch(`/api/process/\${this.selectedModel}`, {
                method: 'POST',
                body: formData
            });

            const result = await response.json();

            if (!result.success) {
                throw new Error(result.error || 'Feldolgozási hiba');
            }

        } catch (error) {
            console.error('Processing error:', error);
            this.showError(error.message);
            this.isProcessing = false;
            this.updateProcessButton();
            this.hideProcessingSection();
        }
    }

    showProcessingSection() {
        document.getElementById('upload-section').style.display = 'none';
        document.getElementById('processing-section').style.display = 'block';
        document.getElementById('results-section').style.display = 'none';

        document.getElementById('progress-fill').style.width = '0%';
        document.getElementById('progress-text').textContent = '0%';

        document.getElementById('processing-section').scrollIntoView({
            behavior: 'smooth',
            block: 'center'
        });
    }

    hideProcessingSection() {
        document.getElementById('processing-section').style.display = 'none';
        document.getElementById('upload-section').style.display = 'block';
    }

    updateProcessingStatus(data) {
        const messageEl = document.getElementById('processing-message');
        const progressFill = document.getElementById('progress-fill');
        const progressText = document.getElementById('progress-text');

        if (data.message) {
            messageEl.textContent = data.message;
        }

        if (data.progress !== undefined) {
            progressFill.style.width = `\${data.progress}%`;
            progressText.textContent = `\${data.progress}%`;
        }

        if (data.step && data.total_steps) {
            const progress = Math.round((data.step / data.total_steps) * 100);
            progressFill.style.width = `\${progress}%`;
            progressText.textContent = `\${data.step}/\${data.total_steps} lépés`;
        }
    }

    handleProcessingComplete(data) {
        this.isProcessing = false;
        this.updateProcessButton();

        if (data.success) {
            this.showResults(data.result);
        } else {
            this.showError(data.error || 'Feldolgozási hiba');
            this.hideProcessingSection();
        }
    }

    showResults(result) {
        document.getElementById('processing-section').style.display = 'none';
        document.getElementById('results-section').style.display = 'block';

        const resultsContent = document.getElementById('results-content');
        resultsContent.innerHTML = this.generateResultsHTML(result);

        document.getElementById('results-section').scrollIntoView({
            behavior: 'smooth',
            block: 'start'
        });
    }

    generateResultsHTML(result) {
        const modelName = this.selectedModel;
        const fileName = this.currentFile.name;

        let html = `
            <div class="result-item">
                <div class="result-header">
                    <h3>Feldolgozás eredménye</h3>
                    <span class="result-status success">
                        <i class="fas fa-check-circle"></i> Sikeres
                    </span>
                </div>

                <div class="result-meta">
                    <div class="meta-item">
                        <i class="fas fa-robot"></i>
                        <span>Modell: \${this.getModelDisplayName(modelName)}</span>
                    </div>
                    <div class="meta-item">
                        <i class="fas fa-file"></i>
                        <span>Fájl: \${fileName}</span>
                    </div>
                    <div class="meta-item">
                        <i class="fas fa-clock"></i>
                        <span>Idő: \${new Date().toLocaleTimeString('hu-HU')}</span>
                    </div>
                </div>
        `;

        if (result.type === 'image') {
            html += `
                <div class="result-details">
                    <h4>Eredmény részletei:</h4>
                    <ul>
                        \${result.scale_factor ? `<li>Skála szorzó: \${result.scale_factor}x</li>` : ''}
                        \${result.zoom_factor ? `<li>Zoom szorzó: \${result.zoom_factor}x</li>` : ''}
                        \${result.size ? `<li>Méret: \${result.size.width}x\${result.size.height}</li>` : ''}
                        \${result.quality_score ? `<li>Minőségi pontszám: \${(result.quality_score * 100).toFixed(1)}%</li>` : ''}
                        \${result.processing_time ? `<li>Feldolgozási idő: \${result.processing_time.toFixed(1)}s</li>` : ''}
                    </ul>
                </div>
            `;
        } else if (result.type === 'video') {
            html += `
                <div class="result-details">
                    <h4>Videó részletei:</h4>
                    <ul>
                        <li>Időtartam: \${result.duration}s</li>
                        <li>FPS: \${result.fps}</li>
                        <li>Felbontás: \${result.resolution}</li>
                        \${result.prompt_used ? `<li>Prompt: "\${result.prompt_used}"</li>` : ''}
                    </ul>
                </div>
            `;
        }

        html += `
                <div class="result-actions">
                    <button class="btn-secondary" onclick="app.downloadResult()">
                        <i class="fas fa-download"></i>
                        Letöltés
                    </button>
                    <button class="btn-secondary" onclick="app.shareResult()">
                        <i class="fas fa-share"></i>
                        Megosztás
                    </button>
                </div>
            </div>
        `;

        return html;
    }

    getModelDisplayName(modelName) {
        const displayNames = {
            chain_of_zoom: 'Chain-of-Zoom',
            phhofm_sisr: 'Phhofm SISR',
            ltx_video: 'LTX-Video',
            dit_sr: 'DiT-SR',
            urae: 'URAE'
        };
        return displayNames[modelName] || modelName;
    }

    downloadResult() {
        this.showSuccess('Letöltés elkezdődött');
    }

    shareResult() {
        if (navigator.share) {
            navigator.share({
                title: 'AI Modellhub Eredmény',
                text: 'Nézd meg mit hoztam létre az AI Modellhub alkalmazással!',
                url: window.location.href
            });
        } else {
            navigator.clipboard.writeText(window.location.href);
            this.showSuccess('Link másolva a vágólapra');
        }
    }

    resetApp() {
        this.selectedModel = null;
        this.currentFile = null;
        this.isProcessing = false;

        document.querySelectorAll('.model-card').forEach(card => {
            card.classList.remove('selected');
        });

        document.getElementById('file-preview').innerHTML = '';
        document.getElementById('model-parameters').innerHTML = '';
        document.getElementById('upload-section').style.display = 'block';
        document.getElementById('processing-section').style.display = 'none';
        document.getElementById('results-section').style.display = 'none';

        this.updateProcessButton();

        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    showSettings() {
        alert('Beállítások: Magyar nyelv, Sötét téma, Értesítések bekapcsolva');
    }

    showError(message) {
        this.showNotification(message, 'error');
    }

    showSuccess(message) {
        this.showNotification(message, 'success');
    }

    showNotification(message, type = 'info') {
        const notification = document.createElement('div');
        notification.className = `notification \${type}`;
        notification.innerHTML = `
            <div class="notification-content">
                <i class="fas fa-\${type === 'error' ? 'exclamation-circle' : type === 'success' ? 'check-circle' : 'info-circle'}"></i>
                <span>\${message}</span>
            </div>
        `;

        document.body.appendChild(notification);

        setTimeout(() => {
            notification.style.animation = 'slideIn 0.3s ease-out reverse';
            setTimeout(() => {
                if (notification.parentNode) {
                    notification.parentNode.removeChild(notification);
                }
            }, 300);
        }, 3000);
    }
}

// Initialize app
document.addEventListener('DOMContentLoaded', () => {
    window.app = new AIModelHub();
});
    </script>
</body>
</html>
"""

